import{_ as o,o as e,c as s,a2 as a}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"セッション","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/sessions.md","filePath":"ja/guides/sessions.md","lastUpdated":1792323081000}'),r={name:"ja/guides/sessions.md"};function n(d,t,i,c,l,h){return e(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="セッション" tabindex="-1">セッション <a class="header-anchor" href="#セッション" aria-label="Permalink to &quot;セッション&quot;">​</a></h1><p><strong>セッション</strong> は、ユーザーと Bot の間の独立した会話スレッドです。各スレッドは専用のコンテキストと履歴を持ち、話題やタスクを切り替えるときは新しいセッションを開くのが普通です。</p><hr><h2 id="なぜ分離するのか" tabindex="-1">なぜ分離するのか <a class="header-anchor" href="#なぜ分離するのか" aria-label="Permalink to &quot;なぜ分離するのか&quot;">​</a></h2><p>Bot と話した内容はすべて現在のセッションに積まれていきます。<strong>新しいセッションを開く</strong> とコンテキストが切り替わります。古い記録は残りますが、現在のスレッドの推論にはもう参加しません。</p><p>セッションは <strong>Bot</strong> 単位で分かれます。各 Bot がそれぞれ自分のセッション群を持ち、混ざることはありません。</p><hr><h2 id="セッションタイプ" tabindex="-1">セッションタイプ <a class="header-anchor" href="#セッションタイプ" aria-label="Permalink to &quot;セッションタイプ&quot;">​</a></h2><p>Memoh は 5 種類のセッションで異なる活動を区別します。</p><table tabindex="0"><thead><tr><th>タイプ</th><th>説明</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>最も一般的な、ユーザーが始める会話。デフォルトはこれです。</td></tr><tr><td><strong>Discuss</strong></td><td>「観察」寄りのモード。Bot はデフォルトで黙っていてよく、モデルの出力は内心の独白として扱われます。送信系のアクションを使ったときだけ、チャネルに向けて本当に発言したことになります。</td></tr><tr><td><strong>Schedule</strong></td><td>cron によってトリガーされます。</td></tr><tr><td><strong>Subagent</strong></td><td>サブエージェントに委任されたときに作られます。</td></tr><tr><td><strong>ACP Agent</strong></td><td>チャットワークスペースから、有効化済みの ACP 互換コーディングエージェントを使ったときに作られます。</td></tr></tbody></table><p>通常の <code>/new chat</code>・<code>/new discuss</code> が直接作成するのは <strong>Chat</strong> と <strong>Discuss</strong> だけです。<strong>ACP Agent</strong> セッションは Agents/ACP ワークフローが作成・管理します。Schedule と Subagent は主にシステムが作成し、一覧では読み取り専用の記録のように見えます。</p><h3 id="chat-と-discuss-の違い" tabindex="-1">Chat と Discuss の違い <a class="header-anchor" href="#chat-と-discuss-の違い" aria-label="Permalink to &quot;Chat と Discuss の違い&quot;">​</a></h3><p><strong>Chat</strong>：</p><ul><li>普通のアシスタントとのやり取りのように振る舞う</li><li>ユーザーが 1 つ送れば、通常は目に見える返信が 1 つ返ってくることを期待する</li><li>ウェブやダイレクトメッセージでは多くの場合これがデフォルト</li></ul><p><strong>Discuss</strong>：</p><ul><li>多くはグループで登場し、Bot はみんなの会話を<strong>見ている</strong></li><li>直接のテキスト出力はほとんどが内心の独白として扱われる</li><li>チャネルに本当に発言するには、明示的な <code>send</code> などのアクションが必要</li><li><strong>黙っていることも正常な選択肢</strong></li></ul><p>Discuss があることで、Bot は一言ごとに返事をするカスタマーサポートではなく、「話に加わるかどうかは自分で決める」グループの一員らしく振る舞えます。</p><hr><h2 id="new-で新しいセッションを開く" tabindex="-1"><code>/new</code> で新しいセッションを開く <a class="header-anchor" href="#new-で新しいセッションを開く" aria-label="Permalink to &quot;`/new` で新しいセッションを開く&quot;">​</a></h2><p>同じルート上で <code>/new</code> を使うと新しいセッションを開けます。古い履歴は削除されず、<strong>現在の</strong> コンテキストが切り替わるだけです。</p><ul><li><code>/new</code>：現在の場面のデフォルトタイプで作成</li><li><code>/new chat</code>：通常の chat を強制</li><li><code>/new discuss</code>：discuss を強制</li></ul><p>ACP Agent セッションは <code>/new</code> では作成されません。先に Bot 詳細の <strong>エージェント</strong> タブで ACP 互換エージェントを有効にし、チャットワークスペースから起動します。</p><p><strong>内蔵のウェブチャネル</strong> のデフォルトは <code>chat</code>、<strong>ダイレクトメッセージ</strong> は多くが <code>chat</code>、<strong>外部チャネルのグループチャット</strong> は多くが <code>discuss</code> です。</p><p><strong>内蔵のウェブチャット</strong> は <code>/new discuss</code> に対応していません。discuss を使いたい場合は、Telegram や Discord などの実際のチャネルを使ってください。</p><h3 id="外部チャネルでは" tabindex="-1">外部チャネルでは <a class="header-anchor" href="#外部チャネルでは" aria-label="Permalink to &quot;外部チャネルでは&quot;">​</a></h3><p>Telegram、Discord、Feishu などの外部チャネルでは、<code>/new</code>・<code>/new chat</code>・<code>/new discuss</code> をメッセージとして Bot に送ります。すると Bot は、新しいセッションを作り、以降のメッセージをすべてそのスレッドに流し、古いセッションは保持したまま「現在」ではなくします。</p><p>特に役立つのはこんなときです。</p><ul><li>話題を変えたくて、Bot に古いコンテキストを参照してほしくないとき。</li><li>このスレッドが長くなりすぎて、きれいにやり直したいとき。</li><li>別々のタスクの間を行き来するとき。</li></ul><h3 id="アプリでは" tabindex="-1">アプリでは <a class="header-anchor" href="#アプリでは" aria-label="Permalink to &quot;アプリでは&quot;">​</a></h3><p><strong>アプリ</strong> ではサイドバーの <strong>New Session</strong> のほか、セッションの切り替え、検索、タイプによる絞り込み（<code>chat</code>、<code>discuss</code>、<code>schedule</code>、<code>subagent</code>、<code>acp_agent</code>）、名前の変更、削除などができます。</p><hr><h2 id="管理" tabindex="-1">管理 <a class="header-anchor" href="#管理" aria-label="Permalink to &quot;管理&quot;">​</a></h2><h3 id="一覧" tabindex="-1">一覧 <a class="header-anchor" href="#一覧" aria-label="Permalink to &quot;一覧&quot;">​</a></h3><p>現在の Bot のセッションはサイドバーに並びます。各項目にはタイトル、タイプのアイコン、最終アクティブ時刻が表示されます。日常的に気にする <strong>Chat / Discuss</strong> は同じ一覧に混在します。どちらも「人が目にする種類のスレッド」だからです。</p><h3 id="名前の変更" tabindex="-1">名前の変更 <a class="header-anchor" href="#名前の変更" aria-label="Permalink to &quot;名前の変更&quot;">​</a></h3><p>タイトルをクリックすると変更できます。トピックごとに整理するのに便利です。</p><h3 id="削除" tabindex="-1">削除 <a class="header-anchor" href="#削除" aria-label="Permalink to &quot;削除&quot;">​</a></h3><p>セッションを削除すると、そのスレッドの履歴は<strong>完全に</strong>消えます。</p><hr><h2 id="ステータスパネル" tabindex="-1">ステータスパネル <a class="header-anchor" href="#ステータスパネル" aria-label="Permalink to &quot;ステータスパネル&quot;">​</a></h2><p>ステータスパネルと <code>/status</code> が示すのは同じ情報です。このセッションのメッセージ数、<strong>コンテキスト使用量</strong>（<code>context_window</code> に対する割合）、<strong>キャッシュヒット</strong>、読み書き量、<strong>このスレッドで使われたスキル</strong> など。ここには <strong>今すぐ圧縮</strong> があり、トリガーされるのは <a href="./compaction.html">セッションコンテキスト圧縮</a> であって、メモリのエントリーを書き換えるものではありません。</p><hr><h2 id="他の機能との関係" tabindex="-1">他の機能との関係 <a class="header-anchor" href="#他の機能との関係" aria-label="Permalink to &quot;他の機能との関係&quot;">​</a></h2><ul><li><strong>Discuss</strong> は「グループで多く見て少なく話す」ためのものです。</li><li><strong>Schedule</strong> も時刻が来るとセッションを生成し、cron コマンドの実行結果を確認できます。</li><li><strong>Subagent</strong> はそれぞれ専用のセッションを持ち、委任されたタスクと対応します。サブエージェントは親 Bot のツール一式（ワークスペース、ブラウザ、メモリ、MCP）をほぼそのまま使えますが、ユーザーに直接メッセージを送ること、ユーザーに質問すること、さらにサブエージェントを重ねることはできません。委任の際、Bot はサブエージェントごとに別のチャットモデルを選ぶことも、現在の会話コンテキストを fork して渡すこともできます。セッション情報パネルで、現在アクティブなサブエージェントを確認できます。</li><li><strong>ACP Agent</strong> は、チャットワークスペースから起動したコーディングエージェントの作業を記録します。</li><li><strong>長期メモリ</strong> は Bot 全体で共有されます。どのスレッドから抽出されたものでも、他のスレッドからも検索できます（設定で許可している前提で）。</li></ul>',44)])])}const p=o(r,[["render",n]]);export{u as __pageData,p as default};
